  var n = data.length;
  var gap = 4;
  var barH = Math.floor((PH - (n - 1) * gap) / n);
  var hi = Math.ceil(Math.max.apply(null, data.map(function(d){ return d.v; })) / 5) * 5;
  function xp(v){ return margin.left + v / hi * PW; }
  function rowTop(i){ return margin.top + i * (barH + gap); }
  function rowMid(i){ return rowTop(i) + barH / 2; }
  var plotL = margin.left, plotR = margin.left + PW, plotT = margin.top, plotB = margin.top + PH;

  // 1. gridlines
  for (var t = 0; t < hi; t += 5){
