    svg.appendChild(el("rect", {x: plotL, y: rowTop(i), width: xp(data[i].v) - plotL, height: barH, fill: "#4a5568"}));
  }

  // 4. axis lines
  svg.appendChild(el("line", {x1: plotL, x2: plotR, y1: plotB, y2: plotB, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: plotL, x2: plotL, y1: plotT, y2: plotB, stroke: "#d8d8d8", "stroke-width": 1}));

  // 6. gold pill on the bar tip of the highest rate, left of the tip
  var pillText = data[0].v.toFixed(2) + "%";
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var tipX = xp(data[0].v);
  var pillX = tipX - pillW - 6;
  var pillY = rowMid(0) - pillH / 2;
  if (pillX < plotL) pillX = plotL;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(tx(pillX + pillW / 2, pillY + pillH / 2 + 3, pillText, "middle", 9, "#111111", 700));

  // 7. labels and annotations
  for (var r = 0; r < n; r++){
    svg.appendChild(tx(margin.left - 5, rowMid(r) + 3, data[r].c, "end", 8.5, "#aaaaaa", 400));
    if (r !== 0) svg.appendChild(tx(xp(data[r].v) - 6, rowMid(r) + 3, data[r].v.toFixed(2) + "%", "end", 8.5, "#ffffff", 700));
  }
  var notes = [0, 2, n - 1];
  notes.forEach(function(idx){
    var dollars = Math.round(data[idx].v * 100);
    var label = "$" + dollars.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",") + " per $10,000 of loss";
    svg.appendChild(tx(plotL + 8, rowMid(idx) + 3, label, "start", 8, "#ffffff", 400));
  });
  for (var k = 0; k < hi; k += 5){
    svg.appendChild(tx(xp(k), plotB + 14, k + "%", "middle", 8, "#999999", 400));
  }
  svg.appendChild(tx(margin.left + PW / 2, plotB + 30, "Top combined federal and provincial tax rate on capital gains, 2026 (50% inclusion)", "middle", 8, "#999999", 400));

