  var boc = [["2024-04-01",5.00],["2024-06-05",4.75],["2024-07-24",4.50],["2024-09-04",4.25],["2024-10-23",3.75],["2024-12-11",3.25],["2025-01-29",3.00],["2025-03-12",2.75],["2025-09-17",2.50],["2025-10-29",2.25],["2026-10-22",2.25]];
  var fed = [["2024-04-01",5.50],["2024-09-18",5.00],["2024-11-07",4.75],["2024-12-18",4.50],["2025-09-17",4.25],["2025-10-29",4.00],["2025-12-10",3.75],["2026-09-16",4.00],["2026-10-22",4.00]];
  var margin = {left: 62, right: 24, top: 18, bottom: 46};
  var W = 680, H = 300;
  var PW = W - margin.left - margin.right;
  var PH = H - margin.top - margin.bottom;
  var plotL = margin.left, plotR = margin.left + PW, plotT = margin.top, plotB = margin.top + PH;
  var all = boc.concat(fed);
  var vmin = Math.min.apply(null, all.map(function(p){ return p[1]; }));
  var vmax = Math.max.apply(null, all.map(function(p){ return p[1]; }));
  var lo = vmin - 0.25, hi = vmax + 0.25;
  var t0 = dn(boc[0][0]), t1 = dn(boc[boc.length - 1][0]);
  function xp(d){ return margin.left + (dn(d) - t0) / (t1 - t0) * PW; }
  function yp(v){ return plotB - (v - lo) / (hi - lo) * PH; }
  function stepPath(series){
    var d = "M" + xp(series[0][0]) + "," + yp(series[0][1]);
    for (var i = 1; i < series.length; i++) d += "H" + xp(series[i][0]) + "V" + yp(series[i][1]);
    return d;
  }

  // 1. gridlines
  for (var g = Math.ceil(lo / 0.5) * 0.5; g <= hi; g += 0.5){
    svg.appendChild(el("line", {x1: plotL, x2: plotR, y1: yp(g), y2: yp(g), stroke: "#ececec", "stroke-width": 0.5}));
  }

  // event band: Bank of Canada on hold since the last cut
  var holdX = xp("2025-10-29");
  svg.appendChild(el("rect", {x: holdX, y: plotT, width: plotR - holdX, height: PH, fill: "#c0392b", "fill-opacity": 0.05}));

  // 3. series paths
  svg.appendChild(el("path", {d: stepPath(fed), fill: "none", stroke: "#6b7280", "stroke-width": 1.5}));
  svg.appendChild(el("path", {d: stepPath(boc), fill: "none", stroke: "#4a5568", "stroke-width": 2}));

  // 4. axis lines
  svg.appendChild(el("line", {x1: plotL, x2: plotR, y1: plotB, y2: plotB, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: plotL, x2: plotL, y1: plotT, y2: plotB, stroke: "#d8d8d8", "stroke-width": 1}));

  // 5. event marker line and endpoint dots (dots stay at the data points)
  var hikeX = xp("2026-09-16");
  svg.appendChild(el("line", {x1: hikeX, x2: hikeX, y1: plotT, y2: plotB, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
  var bocLast = boc[boc.length - 1], fedLast = fed[fed.length - 1];
  var lastX = xp(bocLast[0]);
  svg.appendChild(el("circle", {cx: lastX, cy: yp(bocLast[1]), r: 4, fill: "#4a5568"}));
  svg.appendChild(el("circle", {cx: lastX, cy: yp(fedLast[1]), r: 4, fill: "#6b7280"}));

  // 6. gold pill on the Bank of Canada endpoint, left of the endpoint
  var pillText = bocLast[1].toFixed(2) + "%";
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var pillX = lastX - pillW - 6;
  var pillY = yp(bocLast[1]) - pillH / 2;
  if (pillX < plotL) pillX = plotL;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(tx(pillX + pillW / 2, pillY + pillH / 2 + 3, pillText, "middle", 9, "#111111", 700));

  // 7. labels and annotations
  for (var a = Math.ceil(lo / 0.5) * 0.5; a <= hi; a += 0.5){
    svg.appendChild(tx(margin.left - 6, yp(a) + 3, a.toFixed(1) + "%", "end", 8.5, "#aaaaaa", 400));
  }
  var xt = [["2024-07-01","Jul 2024"],["2025-01-01","Jan 2025"],["2025-07-01","Jul 2025"],["2026-01-01","Jan 2026"],["2026-07-01","Jul 2026"]];
  xt.forEach(function(t){ svg.appendChild(tx(xp(t[0]), plotB + 14, t[1], "middle", 8, "#999999", 400)); });
  svg.appendChild(tx(plotL + 8, yp(fed[0][1]) - 6, "FED FUNDS UPPER BOUND", "start", 7.5, "#888888", 400));
  svg.appendChild(tx(plotL + 8, yp(boc[0][1]) - 6, "BANK OF CANADA TARGET", "start", 7.5, "#888888", 400));
  svg.appendChild(tx(holdX + (plotR - holdX) / 2, plotT + 9, "BOC HOLD, 7 DECISIONS", "middle", 7, "#c0392b", 700));
  var evLabel = "FED HIKE SEP 16";
  var evW = Math.ceil(evLabel.length * 7 * 0.68);
  var nearRight = (hikeX + evW + 3) > plotR;
  svg.appendChild(tx(nearRight ? hikeX - 3 : hikeX + 3, plotT + 22, evLabel, nearRight ? "end" : "start", 7, "#1a3560", 700));
  svg.appendChild(tx(hikeX - 6, yp(fedLast[1]) - 8, "FED " + fedLast[1].toFixed(2) + "%", "end", 8, "#444444", 700));

  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: Bank of Canada announcement history via nesto.ca; Federal Reserve FOMC decisions via Finder. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">The Fed series shows the upper bound of the target range and the Bank of Canada series shows the overnight rate target. The Fed raised on September 16, 2026, and the Bank has held at 2.25% since its cut on October 29, 2025.</p>
<p>Markets put the chance of a further Fed increase on October 28 between 14% and 20%, depending on the source, and a December increase at about 74%, according to prediction-market averages. The Canadian dollar has absorbed some of the divergence, trading near 71 US cents on October 19 and 20.</p>
<h2>The Transmission to Fixed Mortgage Rates</h2>
<p>Lenders price five-year fixed mortgages off the Government of Canada five-year yield, not the overnight rate. That yield neared 4% on October 5, roughly 100 basis points above its level a year earlier, with nearly 40% of the increase arriving in the past month, according to Bloomberg data cited by Benefits and Pensions Monitor.</p>
<p>Prime-linked and variable borrowing responds to the overnight rate directly, so a hike on October 28 would feed straight into it. Fixed-rate pricing has already moved: on October 19, when the hike odds jumped, the two-year yield rose 14 basis points and the TSX fell 0.7%.</p>
<p>October 28 settles whether the Bank is willing to act on expectations before core inflation confirms them. A hold with a higher forecast would tell markets the Bank is prepared to wait. A hike would tell them expectations are the priority.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">What They''re Feeling</div>
<p>Clients with mortgages or lines of credit are anxious about a rate increase that markets treat as near certain, and confused by headlines that say inflation is 3.1% while the core measures the Bank itself prefers are below 2%. Clients holding bonds or GICs have a different worry: whether yields at 4% mean they have missed something. Underneath, most want to know whether they should do anything before October 28.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">What to Say</div>
<div class="script-box">There are two stories in the news this week, and both are true. Headline inflation is 3.1% because gasoline is up 27.8%, and the measures the Bank of Canada trusts most for underlying inflation are below 2%. The Bank decides on October 28, and markets are pricing a quarter-point increase, although many economists expect a hold. I do not know which it will be, and neither does anyone else. What I can tell you is what each outcome would mean for you. If the Bank raises, variable-rate and prime-linked borrowing gets more expensive immediately, and fixed rates have already moved ahead of the decision. If it holds, we are likely to see a higher inflation forecast and the same uncertainty about December. Your plan does not depend on guessing right. Let us look at your renewal dates, your variable-rate exposure and your cash needs for the next 12 months, and make sure none of them is exposed to either outcome.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Who''s Affected</div>
<p><strong>High impact:</strong> Variable-rate and prime-linked borrowers, including lines of credit and business loans, and clients with a fixed mortgage renewing in the next 12 months, who will price off a five-year yield near 4%.</p>
<p><strong>Mixed impact:</strong> Retirees holding bonds, whose existing holdings lose value as yields rise while new purchases earn more, and clients with US dollar income or expenses, since the Canadian dollar has been trading near 71 US cents.</p>
<p><strong>Potential benefit:</strong> Savers rolling over GICs or holding cash in short-term deposits, who benefit if rates rise, and clients with energy holdings, since the oil price assumption is driving the forecast revision.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Action Checklist</div>
<div class="checklist-item">List every client with a variable-rate mortgage, line of credit or prime-linked loan and record the current rate and payment.</div>
<div class="checklist-item">List every fixed mortgage renewing in the next 12 months and note the renewal date beside the five-year yield, near 4% as of October 5.</div>
<div class="checklist-item">Review bond and GIC maturities in the next six months and flag any that roll over around October 28 or December 9.</div>
<div class="checklist-item">Prepare a one-page summary of the four signals: headline CPI 3.1%, CPI-trim 1.8% and CPI-median 1.9%, unemployment 6.5%, and the Fed at 3.75% to 4.00%.</div>
<div class="checklist-item">Calendar October 28 for the Bank of Canada decision and Monetary Policy Report and book same-day follow-up calls with the most exposed clients.</div>
<div class="checklist-item">Document each client conversation about rate risk, including the scenarios discussed.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Follow-Up Email Template</div>
<div class="email-box" id="respond-email">
<strong>Subject:</strong> The Bank of Canada decision on October 28 and what it means for you<br><br>
Hi [Client Name],<br><br>
Thank you for speaking with me today. Here is a short summary of what we covered about the Bank of Canada decision on October 28.<br><br>
Headline inflation is 3.1%, driven by gasoline, while the measures the Bank watches most closely for underlying inflation are 1.8% and 1.9%. Markets expect a quarter-point increase, and many economists expect a hold. Neither outcome changes your long-term plan, but each affects borrowing costs and short-term yields differently.<br><br>
As agreed, I will review your renewal dates and any variable-rate borrowing before the decision, and I will contact you on the afternoon of October 28 to talk through what was announced.<br><br>
[Your Name]<br><br>
<em>This communication is for educational purposes only and does not constitute personalized investment advice.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copy email</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Client Profiles to Target</div>
<p><strong>Homeowners with a mortgage renewing in the next 12 months:</strong> the five-year yield near 4% sets their fixed renewal pricing, and many have not compared fixed and variable under a hike scenario.</p>
<p><strong>Self-directed investors holding bonds, bond funds or GICs:</strong> they are watching yields rise on both sides of the border with no framework for what a Bank of Canada hold or hike changes.</p>
<p><strong>Business owners with prime-linked credit:</strong> a quarter-point increase on October 28 flows directly into their borrowing costs, and the Monetary Policy Report arrives the same day.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Opening Line</div>
<div class="script-box">The Bank of Canada decides on rates next Wednesday, markets are pricing an increase, and the core inflation measures the Bank itself prefers are below target. I am calling people who manage their own finances to ask how they are planning for either outcome.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Value Proposition</div>
<p>Rate decisions are visible and the consequences are personal: a renewal, a line of credit, a GIC maturity. A self-directed investor can read the headlines but has no one to translate them into their own situation, particularly when the signals disagree, as they do this week.</p>
<p>An advisor offers a scenario-based view: what a hold, a hike and a higher forecast each mean for this household over the next 12 months. A decision that arrives with a full Monetary Policy Report on October 28 gives a natural reason to ask for a conversation before it lands.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Discovery Questions</div>
<div class="checklist-item">How are you thinking about the Bank of Canada decision next week?</div>
<div class="checklist-item">Do you have a mortgage renewal, line of credit or other borrowing that depends on interest rates in the next year?</div>
<div class="checklist-item">Is your borrowing fixed or variable, and when did you last compare the two?</div>
<div class="checklist-item">What do you hold for short-term cash and income, and when do those holdings mature?</div>
<div class="checklist-item">If the Bank raised rates and also raised its inflation forecast, what would you change, if anything?</div>
<div class="checklist-item">Who do you talk to when rate headlines conflict with each other?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Prospecting Email Template</div>
<div class="email-box" id="prospect-email">
<strong>Subject:</strong> Before the Bank of Canada decides on October 28<br><br>
Hi [Prospect Name],<br><br>
The Bank of Canada announces its rate decision on October 28. Markets are pricing an increase, many economists expect a hold, and the core inflation measures the Bank itself prefers are below its 2% target. The decision arrives with a full Monetary Policy Report.<br><br>
Whichever way it goes, it affects variable-rate borrowing, fixed mortgage renewals and short-term yields. I am offering a short call to walk through what each scenario would mean for your situation. Would 20 minutes this week or early next week work?<br><br>
[Your Name]<br><br>
<em>This communication is for educational purposes only and does not constitute personalized investment advice.</em>
</div>
