    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (txt !== undefined) e.textContent = txt;
    return e;
  }
  function tx(x, y, s, anchor, size, fill, weight){
    return el("text", {x: x, y: y, "text-anchor": anchor, "font-size": size, "font-weight": weight || 400, fill: fill, "font-family": FONT}, s);
  }
  function dn(s){ var p = s.split("-"); return Date.UTC(+p[0], +p[1] - 1, +p[2]) / 86400000; }
  function fmt(v){ return Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ","); }
  var svg = document.createElementNS(NS, "svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  var px = [["2026-09-16",35491.27],["2026-09-17",35874.26],["2026-09-18",35806.65],["2026-09-21",36009.40],["2026-09-22",36335.61],["2026-09-23",35751.43],["2026-09-24",35706.46],["2026-09-25",35800.89],["2026-09-28",35489.86],["2026-09-29",35460.27],["2026-09-30",35235.87],["2026-10-01",35154.76],["2026-10-02",35502.65],["2026-10-05",35518.55],["2026-10-06",35649.51],["2026-10-07",35041.86],["2026-10-08",35145.38],["2026-10-09",35664.62],["2026-10-13",35983.98],["2026-10-14",35584.46],["2026-10-15",36137.10],["2026-10-16",36176.55],["2026-10-19",35928.63],["2026-10-20",36107.96],["2026-10-21",36324.99]];
  var record = 37069.11;
  var margin = {left: 62, right: 24, top: 18, bottom: 46};
  var W = 680, H = 300;
  var PW = W - margin.left - margin.right;
  var PH = H - margin.top - margin.bottom;
  var plotL = margin.left, plotR = margin.left + PW, plotT = margin.top, plotB = margin.top + PH;
  var lo = 34800, hi = 37200;
  var t0 = dn(px[0][0]), t1 = dn(px[px.length - 1][0]);
  function xp(d){ return plotL + (dn(d) - t0) / (t1 - t0) * PW; }
  function yp(v){ return plotB - (v - lo) / (hi - lo) * PH; }

  // 1. gridlines
  for (var g = 35000; g <= 37000; g += 500){
    svg.appendChild(el("line", {x1: plotL, x2: plotR, y1: yp(g), y2: yp(g), stroke: "#ececec", "stroke-width": 0.5}));
  }
  // 2. reference line: August record close
  svg.appendChild(el("line", {x1: plotL, x2: plotR, y1: yp(record), y2: yp(record), stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
  // event marker line: October 19 repricing
  var evX = xp("2026-10-19");
  svg.appendChild(el("line", {x1: evX, x2: evX, y1: plotT, y2: plotB, stroke: "#c0392b", "stroke-opacity": 0.4, "stroke-width": 1, "stroke-dasharray": "2,3"}));
  // 3. series
  var d = "";
  for (var i = 0; i < px.length; i++) d += (i ? "L" : "M") + xp(px[i][0]) + "," + yp(px[i][1]);
  svg.appendChild(el("path", {d: d, fill: "none", stroke: "#4a5568", "stroke-width": 2}));
  // 4. axis lines
  svg.appendChild(el("line", {x1: plotL, x2: plotR, y1: plotB, y2: plotB, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: plotL, x2: plotL, y1: plotT, y2: plotB, stroke: "#d8d8d8", "stroke-width": 1}));
  // 5. dots: period low and endpoint
  var low = px[15];
  svg.appendChild(el("circle", {cx: xp(low[0]), cy: yp(low[1]), r: 3.5, fill: "#4a5568"}));
  var last = px[px.length - 1];
  var lx = xp(last[0]), ly = yp(last[1]);
  svg.appendChild(el("circle", {cx: lx, cy: ly, r: 4, fill: "#4a5568"}));
  // 6. gold pill left of the endpoint
  var pillText = fmt(last[1]);
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var pillX = lx - pillW - 6;
  var pillY = ly - pillH / 2;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(tx(pillX + pillW / 2, pillY + pillH / 2 + 3, pillText, "middle", 9, "#111111", 700));
  // 7. labels
  for (var a = 35000; a <= 37000; a += 500){
    svg.appendChild(tx(plotL - 6, yp(a) + 3, fmt(a), "end", 8.5, "#aaaaaa", 400));
  }
  var xt = [["2026-09-21","Sep 21"],["2026-09-28","Sep 28"],["2026-10-05","Oct 5"],["2026-10-12","Oct 12"],["2026-10-19","Oct 19"]];
  xt.forEach(function(t){ svg.appendChild(tx(xp(t[0]), plotB + 14, t[1], "middle", 8, "#999999", 400)); });
  svg.appendChild(tx(plotL + 8, yp(record) - 5, "AUGUST RECORD " + record.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ","), "start", 7.5, "#1a3560", 700));
  svg.appendChild(tx(xp(low[0]), yp(low[1]) + 14, "OCT 7 LOW " + fmt(low[1]), "middle", 7.5, "#444444", 700));
  var evLabel = "OCT 19 HIKE ODDS JUMP";
  var evW = Math.ceil(evLabel.length * 7 * 0.68);
  var nearRight = (evX + evW + 3) > plotR;
  svg.appendChild(tx(nearRight ? evX - 4 : evX + 4, plotB - 8, evLabel, nearRight ? "end" : "start", 7, "#c0392b", 700));
  svg.appendChild(tx(plotL + 8, plotB - 8, "S&P/TSX COMPOSITE DAILY CLOSE", "start", 7.5, "#888888", 400));
  svg.appendChild(tx(margin.left + PW / 2, plotB + 30, "Daily closes, September 16 to October 21, 2026", "middle", 8, "#999999", 400));
  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: YCharts, S&P/TSX Composite daily closing levels; Trading Economics for the August record. &nbsp;|&nbsp; hdq.ca</div>
